import json
from pathlib import Path
p=Path(__file__).resolve().parents[1]/'data'
def read(c):return json.loads((p/(c+'.json')).read_text())
def write(c,d):(p/(c+'.json')).write_text(json.dumps(d,ensure_ascii=False,indent=2))
def add(c,name,slug,url,rid,date,fields,version='ВКонтакте, историческая фанатская публикация',make=False):
 d=read(c);e=next((x for x in d if x['name'].lower()==name.lower()),None)
 if e is None:
  if not make:print('NOT FOUND',c,name);return
  e={'slug':slug,'name':name,'category':c,'type':{'locations':'Острова','zombies':'Зомби'}[c],'purchase':'нет данных','sale':'нет данных','obtain':'нет данных','use':'нет данных','features':'нет данных','versions':version,'sources':[],'image':None,'links':[],'event':'нет данных','prior_records':[]};d.append(e)
 e.setdefault('prior_records',[]);e['prior_records']=[r for r in e['prior_records'] if r.get('original_id')!=rid]+[{'original_id':rid,'original_category':'Прочитанная историческая страница','version':version,'date':date,'fields':fields,'confidence':'Фанатский источник; возможное копирование и изменения после публикации не исключены. Неподписанные иконки определены предварительно по именам файлов.'}]
 if not any(s['url']==url for s in e['sources']):e['sources'].append({'url':url,'label':'Прочитанная отдельная страница'})
 write(c,d)
